<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<header class="page-heading department-heading"><div class="shell"><p class="eyebrow">FAST</p><h1><?=View::escape($item['title'])?></h1></div></header><?php foreach($sections as$s):?><section class="section"><div class="shell"><?php if($s['subheading']):?><p class="eyebrow"><?=View::escape($s['subheading'])?></p><?php endif;?><?php if($s['heading']):?><h2><?=View::escape($s['heading'])?></h2><?php endif;?><?php if($s['media_path']):?><img src="<?=View::escape($baseUrl.ltrim(str_replace('public/','',$s['media_path']),'/'))?>" alt="<?=View::escape($s['media_alt_text']??'')?>"><?php endif;?><?php if($s['body']):?><div class="prose"><?=View::richText($s['body'])?></div><?php endif;?><?php if($s['button_label']&&$s['button_url']):?><a class="button button-primary" href="<?=View::escape($s['button_url'])?>"><?=View::escape($s['button_label'])?></a><?php endif;?></div></section><?php endforeach;?>
